"""Beaker-on-hotplate task: scene loading, start-up settle, the success check and the points the neck camera must frame.

Plain functions and flat dicts (src/task_config.py), no classes. The drive -> pedestal -> arms -> neck staging sequence is NOT
here: it is the scripted source in src/staging_source.py, which uses the helpers of this file (framing_points, wrap).

make_task() packages the task for the generic episode runner (src/episode_runner.py): a dictionary that says how to reset the scene, which policy
to run, how to check success and what the time limits are (see the runner's docstring for the keys). rebuild_task() is what replay calls (from the
recipe stored in a recording) to rebuild the model. run_beaker_episode() is a shorthand for tests that builds the task and runs one episode.

Reused from the repo: src.simulator.RobotSimulator (scene load, arm / finger position actuators, cameras, the
placeholder pedestal lift, the camera neck) and the start-up of experiments/combined_controller.py / pedestal_lift_test.py (warm-up
with the arms held at zero, capture of the drooped pose as the resting pose, short re-settle with it held).
"""

import math
from pathlib import Path

import mujoco
import numpy as np

from src import robot_specs
from src.neck import neck_ids, set_neck_pose
from src.robot_helpers import arm_ids  # noqa: F401  (the experiments import it from here)
from src.simulator import RobotSimulator
from src.task_config import EPISODE_CFG, STAGING_CFG, SUCCESS_CFG, TASK_CFG

PROJECT_ROOT = Path(__file__).resolve().parent.parent


# ----------------------------------------------------------------------------------------------------------
# Small helpers
# ----------------------------------------------------------------------------------------------------------
def wrap(a):
    """Wraps an angle to the interval (-pi, pi].

    Args:
        a (float): Angle in radians.

    Returns:
        float: The same angle in radians, wrapped to (-pi, pi].
    """
    return math.atan2(math.sin(a), math.cos(a))


def yaw_to_quat(yaw):
    """Converts a rotation about the world z axis to a quaternion.

    Args:
        yaw (float): Rotation about z in radians.

    Returns:
        numpy.ndarray: Unit quaternion (w, x, y, z) of 4 values, MuJoCo's order.
    """
    return np.array([math.cos(yaw / 2), 0.0, 0.0, math.sin(yaw / 2)])


def bench_top_z(model):
    """Returns the height of the top surface of the bench.

    Args:
        model (mujoco.MjModel): A model with a box geom named "bench_top".

    Returns:
        float: World z of the top face of the geom "bench_top", in metres (its centre height plus its half height).
    """
    g = model.geom("bench_top")
    return float(model.geom_pos[g.id][2] + model.geom_size[g.id][2])


def apply_task_poses(model, data, cfg=TASK_CFG):
    """Writes the object poses from the config into the model and data, without stepping.

    The hotplate is a static body, so moving it is a body_pos edit of the model; the beaker is a free joint, so its
    position and orientation go into qpos, with its velocity set to zero. Both rest on the bench top (see bench_top_z), the beaker
    starting beaker_settle_clearance above it. The kinematics are updated with mj_forward.

    Args:
        model (mujoco.MjModel): The task model; its body_pos for "task_hotplate" is changed.
        data (mujoco.MjData): Its data; the qpos and qvel of the joint "task_beaker_free" are changed.
        cfg (dict): Task configuration with the keys "hotplate_xy" and "beaker_xy" (world x, y in metres) and
            "beaker_settle_clearance" (metres). Defaults to task_config.TASK_CFG.
    """
    top = bench_top_z(model)
    hp = model.body("task_hotplate")
    model.body_pos[hp.id] = [cfg["hotplate_xy"][0], cfg["hotplate_xy"][1], top]
    jq = model.joint("task_beaker_free").qposadr[0]
    data.qpos[jq:jq + 7] = [cfg["beaker_xy"][0], cfg["beaker_xy"][1], top + cfg["beaker_settle_clearance"], 1, 0, 0, 0]
    data.qvel[model.joint("task_beaker_free").dofadr[0]:][:6] = 0.0
    mujoco.mj_forward(model, data)


def load_task(cfg=TASK_CFG, cameras=True):
    """Creates a RobotSimulator on the task scene, with the pedestal lift, and places the objects.

    The camera neck is on, as RobotSimulator does by default.

    Args:
        cfg (dict): Task configuration; "scene" is the scene file relative to the project root, and the object poses are
            applied with apply_task_poses. Defaults to task_config.TASK_CFG.
        cameras (bool or list of dict or None): True means robot_specs.CAMERA_SPECS, False or None means no cameras, a list is
            used as the camera specification dictionaries. Defaults to True.

    Returns:
        RobotSimulator: The simulator with the pedestal lift (robot_specs.PEDESTAL_SPECS) and the objects placed.
    """
    cams = robot_specs.CAMERA_SPECS if cameras is True else (cameras or None)
    sim = RobotSimulator(model_path=str(PROJECT_ROOT / cfg["scene"]),
                         cameras=cams,
                         pedestal_lift=robot_specs.PEDESTAL_SPECS)
    apply_task_poses(sim.model, sim.data, cfg)
    return sim


def spawn_and_settle(sim, cfg=TASK_CFG):
    """Places the robot at the spawn pose and brings it to rest like combined_controller.py does.

    The base is dropped from a height of 0.22 m at cfg["spawn_xy"] with yaw cfg["spawn_yaw"]. It is then simulated for
    cfg["warmup_s"] with all non-wheel actuators held at their start command (arms and fingers at zero, the pedestal at its default
    command, the neck at its drive pose) and the base held still except for its height. Then the arm and finger joint angles
    reached are captured as the resting pose and held for cfg["resettle_s"]. The data of `sim` is advanced.

    Args:
        sim (RobotSimulator): The simulator from load_task; its data is changed.
        cfg (dict): Task configuration with the keys "spawn_xy" (world x, y in metres), "spawn_yaw" (radians), "warmup_s" and
            "resettle_s" (seconds). Defaults to task_config.TASK_CFG.

    Returns:
        dict: With the keys
            "hold" (numpy.ndarray): The full ctrl vector that holds the resting pose: the captured arm and finger joint angles,
                the pedestal at its default command (robot_specs.PEDESTAL_SPECS["target_height"]), the neck at its drive pose;
                the wheel motors stay at ctrl 0.
            "ped" (int): Actuator id of the pedestal lift.
            "wheels" (set of int): Actuator ids of the two wheel motors.
            "base_dof" (int): Address in qvel of the base's free joint.
    """
    model, data = sim.model, sim.data
    data.qpos[0:3] = [cfg["spawn_xy"][0], cfg["spawn_xy"][1], 0.22]
    data.qpos[3:7] = yaw_to_quat(cfg["spawn_yaw"])
    mujoco.mj_forward(model, data)

    dof = int(model.jnt_dofadr[0])                   # the base's free joint (the first joint)
    ped = model.actuator(robot_specs.PEDESTAL_SPECS["actuator_name"]).id
    wheels = {model.actuator("left_motor").id, model.actuator("right_motor").id}
    unclaimed = [a for a in range(model.nu) if a not in wheels]
    hold = np.zeros(model.nu)
    hold[ped] = robot_specs.PEDESTAL_SPECS["target_height"]
    neck = neck_ids(model, robot_specs.NECK_SPECS)
    if neck is not None:
        hold[neck["act"]] = robot_specs.NECK_SPECS["drive_pose"]

    def run(seconds):
        """Simulates `seconds` with ctrl set to `hold` and the base held still.

        It reads `hold`, `dof`, `model` and `data` of the enclosing function and steps `data`: each physics step writes `hold`
        into ctrl, sets the base's x and y velocity and its three angular velocities to zero (the height is left to physics so the
        robot settles onto its wheels) and then steps.

        Args:
            seconds (float): Simulated time, in seconds; rounded to a whole number of steps at robot_specs.PHYSICS_HZ.
        """
        for _ in range(int(round(seconds * robot_specs.PHYSICS_HZ))):
            data.ctrl[:] = hold
            data.qvel[dof + 0:dof + 2] = 0.0              # base held still: xy, roll, pitch, yaw rate; z is left to
            data.qvel[dof + 3:dof + 6] = 0.0              # physics so the robot settles onto its wheels
            mujoco.mj_step(model, data)

    run(cfg["warmup_s"])
    for a in unclaimed:                     # capture the drooped pose; kill any residual swing
        if a == ped or (neck is not None and a in neck["act"]):
            continue
        j = int(model.actuator_trnid[a, 0])
        hold[a] = data.qpos[model.jnt_qposadr[j]]
        data.qvel[model.jnt_dofadr[j]] = 0.0
    mujoco.mj_forward(model, data)
    run(cfg["resettle_s"])

    return {"hold": hold, "ped": ped, "wheels": wheels, "base_dof": dof}


# ----------------------------------------------------------------------------------------------------------
# Success check
# ----------------------------------------------------------------------------------------------------------
def check_success(model, data, cfg=SUCCESS_CFG):
    """Checks whether the beaker is standing on the hotplate top and at rest.

    All of: (a) beaker_base xy inside the hotplate top footprint minus a margin, (b) beaker_base z within
    height_tol of hotplate_top z, (c) the beaker's z axis within upright_max_deg of world z, (d) linear speed
    below speed_max.

    Args:
        model (mujoco.MjModel): The task model.
        data (mujoco.MjData): Its current data.
        cfg (dict): Success configuration with the keys "beaker_site", "hotplate_site", "hotplate_plate_geom", "beaker_body",
            "footprint_margin" (m), "height_tol" (m), "upright_max_deg" (degrees) and "speed_max" (m/s). Defaults to
            task_config.SUCCESS_CFG.

    Returns:
        tuple: (success, diagnostics). success (bool) is True if all four conditions hold. diagnostics (dict) has one entry per
        condition, each a dict with "ok" (bool) and the measured value with its limit:
            "a_xy_in_footprint": "offset_xy_m" (beaker base x, y in the hotplate top frame, metres) and "allowed_half_extent_m"
                (half extent of the top plate less the margin, metres).
            "b_height": "dz_m" (beaker base height above the hotplate top, metres) and "tol_m".
            "c_upright": "tilt_deg" (angle between the beaker's z axis and world z, degrees) and "max_deg".
            "d_at_rest": "speed_m_s" (linear speed of the beaker's free joint, metres per second) and "max_m_s".
    """
    base = data.site(cfg["beaker_site"]).xpos
    top = data.site(cfg["hotplate_site"])
    top_pos, top_R = top.xpos, top.xmat.reshape(3, 3)
    half = model.geom_size[model.geom(cfg["hotplate_plate_geom"]).id][:2] - cfg["footprint_margin"]
    local = top_R.T @ (base - top_pos)                       # beaker_base in the hotplate top frame
    dz = float(base[2] - top_pos[2])
    body = model.body(cfg["beaker_body"])
    z_axis = data.xmat[body.id].reshape(3, 3)[:, 2]
    tilt = math.degrees(math.acos(float(np.clip(z_axis[2], -1.0, 1.0))))
    speed = float(np.linalg.norm(data.qvel[model.joint("task_beaker_free").dofadr[0]:][:3]))
    diag = {
        "a_xy_in_footprint": {"ok": bool(np.all(np.abs(local[:2]) <= half)), "offset_xy_m": local[:2].round(4).tolist(),
                              "allowed_half_extent_m": half.round(4).tolist()},
        "b_height": {"ok": abs(dz) <= cfg["height_tol"], "dz_m": round(dz, 4), "tol_m": cfg["height_tol"]},
        "c_upright": {"ok": tilt <= cfg["upright_max_deg"], "tilt_deg": round(tilt, 1), "max_deg": cfg["upright_max_deg"]},
        "d_at_rest": {"ok": speed < cfg["speed_max"], "speed_m_s": round(speed, 4), "max_m_s": cfg["speed_max"]},
    }
    return all(v["ok"] for v in diag.values()), diag


# ----------------------------------------------------------------------------------------------------------
# What the neck camera should frame
# ----------------------------------------------------------------------------------------------------------
def framing_points(model, data, cfg=TASK_CFG):
    """Returns the world points the neck camera has to keep in view for this task: the beaker, the hotplate and the arm's gripper.

    Corners of the beaker's and the hotplate's bounding boxes (so their whole bodies fit, not just their centres) and the
    gripper's tool centre point (TCP), hand origin and finger tips of the arm that carries the task (cfg["arm"], at whatever pose
    it is in).

    Args:
        model (mujoco.MjModel): The task model.
        data (mujoco.MjData): Its current data (the points follow the current poses).
        cfg (dict): Task configuration; "arm" ("left" or "right") picks the gripper. Defaults to task_config.TASK_CFG.

    Returns:
        dict: Maps a point name to its world position (numpy.ndarray of 3 values, metres): "beaker_corner0" to "beaker_corner7",
        "hotplate_corner0" to "hotplate_corner7", "<side>_gripper_tcp", "<side>_gripper_hand", "<side>_gripper_tip0" and
        "<side>_gripper_tip1", where <side> is cfg["arm"]. Empty if the scene has no body "task_beaker".
    """
    if mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_BODY, "task_beaker") < 0:
        return {}
    pts = {}

    def box(name, center, half):
        """Adds the 8 corners of a box to `pts` as "<name>_corner0" to "<name>_corner7".

        Args:
            name (str): Prefix of the point names.
            center (array-like): World position of the box centre, 3 values in metres.
            half (array-like): Half extents of the box along world x, y, z, 3 values in metres.
        """
        for i, (sx, sy, sz) in enumerate(((a, b, c) for a in (-1, 1) for b in (-1, 1) for c in (-1, 1))):
            pts[f"{name}_corner{i}"] = np.array(center) + np.array([sx, sy, sz]) * np.array(half)

    top = bench_top_z(model)
    g = model.geom("task_beaker_glass")
    r, hh = float(model.geom_size[g.id][0]), float(model.geom_size[g.id][1])
    bpos = data.body("task_beaker").xpos
    box("beaker", bpos + [0, 0, hh], [r, r, hh])
    hot = data.body("task_hotplate").xpos
    base = model.geom("task_hotplate_base")
    box("hotplate", hot + [0, 0, float(model.geom_size[base.id][2])], [float(model.geom_size[base.id][0]), float(model.geom_size[base.id][1]),
                                                                       float(model.geom_size[base.id][2])])
    side = cfg["arm"]
    hand = data.body(f"openarm_{side}_hand")
    R = hand.xmat.reshape(3, 3)
    tcp = data.body(f"openarm_{side}_hand_tcp").xpos
    pts[f"{side}_gripper_tcp"] = tcp.copy()
    pts[f"{side}_gripper_hand"] = hand.xpos.copy()
    for k, sgn in enumerate((-1, 1)):                                      # the finger tips: 1.5 cm past the TCP, +-4.5 cm across
        pts[f"{side}_gripper_tip{k}"] = tcp + R @ np.array([0.0, sgn * 0.045, 0.015])
    return pts


# ----------------------------------------------------------------------------------------------------------
# The task for the generic episode runner
# ----------------------------------------------------------------------------------------------------------
def make_task(arm_stage=None, task_cfg=TASK_CFG, staging_cfg=STAGING_CFG, episode_cfg=EPISODE_CFG, success_cfg=SUCCESS_CFG):
    """Packages the beaker task for src/episode_runner.run_episode().

    Args:
        arm_stage (callable | None): Factory arm_stage(model, data) -> stage dictionary for the stage that owns the arms after the handoff (see
            src/sequential_policy.py). None means the hold stage. Defaults to None.
        task_cfg (dict): Task poses. Defaults to TASK_CFG.
        staging_cfg (dict): Staging speeds, ramps and tolerances. Defaults to STAGING_CFG.
        episode_cfg (dict): Time limits and run settings: "timeout_after_handoff" and "operator_timeout" (seconds), "log_hz", "exclusive"
            and "spawn_z" (metres). Defaults to EPISODE_CFG.
        success_cfg (dict): Success check thresholds. Defaults to SUCCESS_CFG.

    Returns:
        dict: The task, with the keys the runner reads: "name", "reset" (model, data -> spawn dict), "make_policy" (model, data -> policy source),
        "check_success" (model, data -> (bool, diagnostics)), "limits" (the time limits and run settings), "log_extras" (model -> (column names,
        row function of data)), "framing_points" (model, data -> world points for the F7 key), "handoff_camera" ("eagle_cam"), "handoff_label"
        ("DONE"), "recipe" (how replay rebuilds the model) and "meta" (configuration saved in a recording).
    """
    def reset(model, data):
        """Resets the simulation state, places the task objects and returns where the robot is to spawn."""
        mujoco.mj_resetData(model, data)
        apply_task_poses(model, data, task_cfg)
        return {"spawn_pos": [task_cfg["spawn_xy"][0], task_cfg["spawn_xy"][1], episode_cfg["spawn_z"]], "spawn_yaw": task_cfg["spawn_yaw"]}

    def make_policy(model, data):
        """Builds the staging stage followed by the arm stage (hold if none was given)."""
        from src.task_policy import make_task_policy         # imported here: task_policy imports staging_source, which imports this file
        return make_task_policy(model, data, task_cfg, staging_cfg, arm_stage(model, data) if arm_stage else None)

    def log_extras(model):
        """Gives the beaker's position as extra log columns."""
        adr = int(model.joint("task_beaker_free").qposadr[0])
        return ["beaker_x", "beaker_y", "beaker_z"], lambda data: [f"{data.qpos[adr + k]:.9f}" for k in range(3)]

    return {"name": "beaker_hotplate", "reset": reset, "make_policy": make_policy,
            "check_success": lambda model, data: check_success(model, data, success_cfg),
            "limits": dict(episode_cfg), "log_extras": log_extras,
            "framing_points": lambda model, data: framing_points(model, data, task_cfg),
            "handoff_camera": "eagle_cam", "handoff_label": "DONE",
            "recipe": {"entry": "src.task_beaker_hotplate:rebuild_task", "cfg": {"task_cfg": task_cfg}},
            "meta": {"task_cfg": task_cfg, "staging_cfg": staging_cfg, "episode_cfg": episode_cfg}}


def rebuild_task(cfg, meta):
    """Rebuilds the model of a recorded beaker episode (called by src/replay.py from a recording's recipe).

    Args:
        cfg (dict): The recipe's configuration: {"task_cfg": the task poses used by the recorded run}.
        meta (dict): The recording's meta.json, whose "robot_specs"/"CAMERA_SPECS" gives the cameras the model was built with.

    Returns:
        tuple: (model, data, reset), where reset(model, data) repeats what the live run did to the state before the loop started.
    """
    task_cfg = cfg["task_cfg"]
    sim = load_task(cfg=task_cfg, cameras=meta["robot_specs"]["CAMERA_SPECS"])

    def reset(model, data):
        """Resets the state and places the task objects, as the task's reset does."""
        mujoco.mj_resetData(model, data)
        apply_task_poses(model, data, task_cfg)

    return sim.model, sim.data, reset


def run_beaker_episode(make_arm_stage, model, data, task_cfg=TASK_CFG, staging_cfg=STAGING_CFG, episode_cfg=EPISODE_CFG, **kwargs):
    """Runs one beaker episode: builds the task with make_task() and calls the generic runner.

    A shorthand for the tests, which vary the arm stage and the configuration.

    Args:
        make_arm_stage (callable | None): Arm stage factory, see make_task().
        model (mujoco.MjModel): The compiled model.
        data (mujoco.MjData): Simulation state.
        task_cfg (dict): Task poses. Defaults to TASK_CFG.
        staging_cfg (dict): Staging configuration. Defaults to STAGING_CFG.
        episode_cfg (dict): Time limits and run settings. Defaults to EPISODE_CFG.
        **kwargs: Passed to src/episode_runner.run_episode() (mode, viewer, out_dir, handoff_frame, held, loop_cfg, record_dir, extra_sources).

    Returns:
        dict: The episode summary of run_episode().
    """
    from src.episode_runner import run_episode
    return run_episode(make_task(make_arm_stage, task_cfg, staging_cfg, episode_cfg), model, data, **kwargs)
